 function updateHud(){$('playerbar').style.width=g.player+'%';$('enemybar').style.width=g.enemy+'%';$('playerpct').textContent=Math.ceil(g.player);$('enemypct').textContent=Math.ceil(g.enemy);$('staminaText').textContent=Math.ceil(g.stamina)+'%';$('landed').textContent=String(g.hits).padStart(2,'0');$('accuracy').textContent=g.attempts?Math.round(g.hits/g.attempts*100)+'%':'—%'}
 function toast(text){const e=$('toast');e.textContent=text;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),650)}
 function message(title,sub){$('message').innerHTML=`<strong>${title}</strong><span>${sub}</span>`;$('message').style.opacity='1';clearTimeout(message.timer);message.timer=setTimeout(()=>{if(g.state==='fight')$('message').style.opacity='0'},1300)}
